const ProfitabilityFeature={id:"profitability",name:"Profitability",icon:"monitoring",route:!1,actions:["openJob","openAddCost","saveCost","openPolicy","savePolicy"],async render(){const t=await DB.getFinancialPolicies(),e=t[t.length-1];return`<div class="fade-in">${App.renderTopHeader({title:"Profitability settings",showBack:!0,backHref:"control",actions:'<button class="btn btn-primary btn-sm" data-action="ProfitabilityFeature.openPolicy"><span class="material-symbols-rounded">add</span>New policy</button>'})}<div class="p-md"><div class="card mb-md"><div class="fw-600">Effective-dated costing</div><div class="fs-13 text-secondary mt-xs">A new policy applies only from its start date. Historic quotes and jobs keep the policy that applied at the time.</div></div>${e?`<div class="card"><div class="fw-600">Current: ${Utils.escapeHtml(e.mode.replaceAll("_"," "))}</div><div class="fs-13 text-secondary mt-xs">From ${Utils.formatDate(e.effectiveFrom,"short")} · commission ${e.commissionRate}% · mileage ${Utils.formatCurrency(e.mileageRate)}/mile · labour ${Utils.formatCurrency(e.labourHourlyCost)}/hour</div></div>`:'<div class="empty-state"><span class="material-symbols-rounded">monitoring</span><div>No costing policy yet</div></div>'}</div></div>`},openPolicy(){const t=new Date;t.setDate(t.getDate()+1),App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>New financial policy</h3><button class="btn btn-ghost btn-sm" aria-label="Close" data-action="App.closeModal"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body"><div class="form-group"><label for="policy-mode">Business mode</label><select class="select" id="policy-mode"><option value="sole_trader">Sole trader</option><option value="commission_advisor">Commission advisor</option><option value="hybrid">Hybrid</option></select></div><div class="form-group"><label for="policy-date">Effective from</label><input class="input" id="policy-date" type="date" value="${Utils.formatDate(t,"iso")}"></div><div class="form-row"><div class="form-group"><label for="policy-commission">Commission %</label><input class="input" id="policy-commission" type="number" min="0" max="100" step="0.01" value="0"></div><div class="form-group"><label for="policy-fee">Payment fee %</label><input class="input" id="policy-fee" type="number" min="0" max="100" step="0.01" value="0"></div></div><div class="form-row"><div class="form-group"><label for="policy-mileage">Mileage per mile</label><input class="input" id="policy-mileage" type="number" min="0" step="0.01" value="${CONFIG.mileageRate||0}"></div><div class="form-group"><label for="policy-labour">Labour per hour</label><input class="input" id="policy-labour" type="number" min="0" step="0.01" value="${CONFIG.minHourlyRate||0}"></div></div><button class="btn btn-primary btn-block" data-action="ProfitabilityFeature.savePolicy">Start policy</button></div>`)},async savePolicy(){try{await DB.createFinancialPolicy({mode:document.getElementById("policy-mode")?.value,effectiveFrom:new Date(`${document.getElementById("policy-date")?.value}T00:00:00`).toISOString(),commissionRate:document.getElementById("policy-commission")?.value,paymentFeeRate:document.getElementById("policy-fee")?.value,mileageRate:document.getElementById("policy-mileage")?.value,labourHourlyCost:document.getElementById("policy-labour")?.value}),App.closeModal(),Toast.show("New policy started; history is unchanged","success"),App.navigate("profitability")}catch(t){Toast.show(t.message||"Could not save policy","error")}},async openJob(t){const e=await DB.getJob(t);if(!e)return Toast.show("Job not found","error");const a=await DB.getJobCosts({jobId:t}),o=await DB.calculateJobProfitability(t,this.estimatedHours(e)),i=a.length?a.map(t=>`<div class="list-row"><span><strong>${Utils.escapeHtml(t.category.replace("_"," "))}</strong><small>${Utils.escapeHtml(t.description||Utils.formatDate(t.incurredAt,"short"))}</small></span><strong>${Utils.formatCurrency(t.amount)}</strong></div>`).join(""):'<p class="hint">No actual job costs logged yet.</p>';App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Job profitability</h3><button class="btn btn-ghost btn-sm" aria-label="Close" data-action="App.closeModal"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body"><div class="stats-grid"><div class="stat-card"><div class="value">${Utils.formatCurrency(o.revenue)}</div><div class="label">Revenue</div></div><div class="stat-card"><div class="value">${Utils.formatCurrency(o.directCost)}</div><div class="label">Direct cost</div></div><div class="stat-card"><div class="value">${Utils.formatCurrency(o.grossProfit)}</div><div class="label">Gross profit</div></div><div class="stat-card"><div class="value">${o.marginPercent.toFixed(2)}%</div><div class="label">Margin</div></div><div class="stat-card"><div class="value">${null==o.effectiveHourlyValue?"—":Utils.formatCurrency(o.effectiveHourlyValue)}</div><div class="label">Profit per hour</div></div></div><p class="hint">${o.financialMode?Utils.escapeHtml(o.financialMode.replace("_"," ")):"No dated financial policy"} · ${Utils.escapeHtml(o.basis.replaceAll("_"," "))}. Payments remain in the separate ledger.</p><h4 class="mt-md">Actual direct costs</h4>${i}<button class="btn btn-primary btn-block mt-md" data-action="ProfitabilityFeature.openAddCost" data-args='${JSON.stringify([e.id,e.orderId])}'>Log direct cost</button></div>`)},estimatedHours(t){const e=new Date(t.scheduledStart),a=new Date(t.scheduledEnd);return!isNaN(e)&&!isNaN(a)&&a>e?(a-e)/36e5:0},openAddCost(t,e){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Log direct cost</h3></div><div class="sheet-body"><div class="form-group"><label for="job-cost-category">Category</label><select class="select" id="job-cost-category"><option value="materials">Materials</option><option value="subcontractor">Subcontractor</option><option value="travel">Travel allocation</option><option value="payment_fee">Payment fee</option><option value="labour">Labour</option><option value="other">Other</option></select></div><div class="form-group"><label for="job-cost-amount">Amount (£)</label><input class="input" id="job-cost-amount" type="number" inputmode="decimal" min="0.01" step="0.01"></div><div class="form-group"><label for="job-cost-description">Description</label><input class="input" id="job-cost-description"></div><button class="btn btn-primary btn-block" data-action="ProfitabilityFeature.saveCost" data-args='${JSON.stringify([t,e])}'>Save cost</button><button class="btn btn-outline btn-block mt-sm" data-action="ProfitabilityFeature.openJob" data-args='${JSON.stringify([t])}'>Cancel</button></div>`)},async saveCost(t,e){const a=Number(document.getElementById("job-cost-amount")?.value);return a>0?(await DB.addJobCost({jobId:t,orderId:e,category:document.getElementById("job-cost-category")?.value,amount:a,description:document.getElementById("job-cost-description")?.value.trim()||"",incurredAt:(new Date).toISOString(),operationId:`job-cost:${t}:${Date.now()}`}),Toast.show("Cost logged","success"),this.openJob(t)):Toast.show("Enter a positive cost","error")}};App.registerFeature(ProfitabilityFeature);
